def second_smallest(lst):
    if not lst:
        raise ValueError("List is empty")
    smallest = float('inf')
    second = float('inf')
    for num in lst:
        if num < smallest:
            second = smallest
            smallest = num
        elif smallest <= num < second:
            second = num
    # If second is still inf, it means all elements are equal or there's only one element
    if second == float('inf'):
        return smallest
    return second

def count(lst):
    true_count = 0
    for el in lst:
        if isinstance(el, bool):
            if el is True:
                true_count += 1
        elif isinstance(el, int):
            if el == 1:
                true_count += 1
            elif el == 0:
                continue
            else:
                raise TypeError(f"Invalid numeric element {el} encountered.")
        else:
            raise TypeError(f"Invalid element type {type(el)} encountered.")
    return true_count

import re

def remove_multiple_spaces(s: str) -> str:
    return re.sub(r'\s+', ' ', s)

def is_decimal(s: str) -> bool:
    if not isinstance(s, str):
        return False
    parts = s.split('.')
    if len(parts) != 2:
        return False
    integer_part, decimal_part = parts
    if not decimal_part.isdigit() or len(decimal_part) != 2:
        return False
    # Allow optional sign on integer part
    if integer_part.startswith(('+', '-')):
        integer_part = integer_part[1:]
    # Integer part can be empty (e.g., ".12"), treat as zero
    if integer_part == '':
        return True
    return integer_part.isdigit()

def is_Two_Alter(s: str) -> bool:
    if len(s) == 1:
        return True

    distinct_chars = set(s)
    if len(distinct_chars) > 2:
        return False

    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            return False

    return True

def max_sub_array_sum(arr):
    if not arr:
        return 0
    max_ending_here = max_so_far = arr[0]
    for x in arr[1:]:
        max_ending_here = max(x, max_ending_here + x)
        max_so_far = max(max_so_far, max_ending_here)
    return max_so_far

def len_log(s):
    words = s.split()
    if not words:
        return 0
    return max(len(word) for word in words)

def double_the_difference(lst):
    '''
    Given a list of numbers, return the sum of squares of the numbers
    in the list that are odd. Ignore numbers that are negative or not integers.
    '''
    return sum(x*x for x in lst if isinstance(x, int) and x >= 0 and x % 2 == 1)

def count_nums(arr):
    def sum_signed_digits(n):
        s = str(abs(n))
        digits = list(map(int, s))
        if n < 0:
            digits[0] = -digits[0]
        return sum(digits)

